protected int findByte(byte value, int pos) {
    // Ensure the buffer exists and has elements
    if (buffer == null || buffer.length == 0) {
        return -1;
    }
    // Normalize starting position
    if (pos < 0) {
        pos = 0;
    }
    if (pos >= buffer.length) {
        return -1;
    }
    // Search for the byte value
    for (int i = pos; i < buffer.length; i++) {
        if (buffer[i] == value) {
            return i;
        }
    }
    // Not found
    return -1;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new NullPointerException("OutputStream is null");
    }
    if (message == null) {
        throw new NullPointerException("Message is null");
    }
    if (schema == null) {
        throw new NullPointerException("Schema is null");
    }
    if (buffer == null) {
        throw new NullPointerException("LinkedBuffer is null");
    }

    // Compute the serialized size of the message
    int size = schema.getSerializedSize(message);

    // Write the length prefix as a varint to the output stream
    CodedOutputStream lengthOut = CodedOutputStream.newInstance(out);
    lengthOut.writeRawVarint32(size);
    lengthOut.flush();

    // Serialize the message into the provided buffer
    byte[] buf = buffer.getBuffer();
    int bufSize = buffer.getSize(); // capacity of the buffer
    if (size > bufSize) {
        // If the buffer is too small, allocate a larger one
        buf = new byte[size];
    }
    CodedOutputStream msgOut = CodedOutputStream.newInstance(buf, 0, buf.length);
    schema.writeTo(message, msgOut);
    msgOut.flush();

    // Write the serialized message bytes to the output stream
    out.write(buf, 0, size);
    return size;
}

