void insertBefore(Bucket bucket){
    if (bucket == null) {
        throw new IllegalArgumentException("bucket cannot be null");
    }
    if (bucket == this) {
        throw new IllegalArgumentException("cannot insert before itself");
    }

    // Detach this bucket from its current position if it is part of a list
    if (this.prev != null) {
        this.prev.next = this.next;
    }
    if (this.next != null) {
        this.next.prev = this.prev;
    }

    // Insert this bucket before the specified bucket
    Bucket prevBucket = bucket.prev;
    this.next = bucket;
    this.prev = prevBucket;
    bucket.prev = this;
    if (prevBucket != null) {
        prevBucket.next = this;
    }
}

