static long compressTimeBucket(long timeBucket, int dayStep) {
    // Validate dayStep
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be positive");
    }
    // Parse year, month, day from the long value
    long year = timeBucket / 10000;
    long month = (timeBucket % 10000) / 100;
    long day = timeBucket % 100;

    // Basic validation of parsed components
    if (year <= 0 || month < 1 || month > 12 || day < 1 || day > 31) {
        throw new IllegalArgumentException("Invalid date format in timeBucket: " + timeBucket);
    }

    // Determine days in the month (accounting for leap years)
    int[] daysInMonth = { 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 };
    if (month == 2) {
        boolean isLeap = (year % 4 == 0) && ((year % 100 != 0) || (year % 400 == 0));
        daysInMonth[1] = isLeap ? 29 : 28;
    }
    if (day > daysInMonth[(int) month - 1]) {
        throw new IllegalArgumentException("Invalid day for month in timeBucket: " + timeBucket);
    }

    // Compute the bucket start day
    long bucketDay = ((day - 1) / dayStep) * dayStep + 1;

    // Construct the compressed time bucket
    return year * 10000 + month * 100 + bucketDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("String is null");
    }
    if (index < 0 || len < 0 || index > str.length() - len) {
        throw new IndexOutOfBoundsException(
                "index=" + index + ", len=" + len + ", str.length()=" + str.length());
    }
    int end = index + len;
    int size = 0;
    for (int i = index; i < end; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(ch)) {
            if (i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
                // Valid surrogate pair -> 4 bytes
                size += 4;
                i++; // Skip low surrogate
            } else {
                // Unpaired high surrogate -> replacement character (3 bytes)
                size += 3;
            }
        } else if (Character.isLowSurrogate(ch)) {
            // Unpaired low surrogate -> replacement character (3 bytes)
            size += 3;
        } else {
            // BMP character that is not ASCII -> 3 bytes
            size += 3;
        }
    }
    return size;
}

