private static String substitute(String value, Properties props, Set<String> seen, int depth) {
    if (depth > 10) {
        return value; // stop recursion
    }
    Pattern pattern = Pattern.compile("\\$\\{([^}]+)\\}");
    Matcher m = pattern.matcher(value);
    StringBuffer sb = new StringBuffer();
    while (m.find()) {
        String var = m.group(1);
        if (seen.contains(var)) {
            // circular reference, skip
            m.appendReplacement(sb, Matcher.quoteReplacement("${" + var + "}"));
            continue;
        }
        String replacement = props.getProperty(var);
        if (replacement == null) {
            // leave placeholder unchanged
            m.appendReplacement(sb, Matcher.quoteReplacement("${" + var + "}"));
        } else {
            // recursively substitute replacement
            seen.add(var);
            String sub = substitute(replacement, props, seen, depth + 1);
            seen.remove(var);
            m.appendReplacement(sb, Matcher.quoteReplacement(sub));
        }
    }
    m.appendTail(sb);
    return sb.toString();
}

