public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u == null) {
        return java.util.Collections.emptyList();
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return java.util.Collections.emptyList();
    }
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    if (path.isEmpty()) {
        return java.util.Collections.emptyList();
    }
    String[] parts = path.split("/", -1);
    java.util.List<PathSegmentImpl> result = new java.util.ArrayList<>(parts.length);
    for (String part : parts) {
        String seg = part;
        if (decode) {
            try {
                seg = java.net.URLDecoder.decode(seg, "UTF-8");
            } catch (java.io.UnsupportedEncodingException e) {
                // UTF-8 is guaranteed to be supported
                throw new RuntimeException(e);
            } catch (IllegalArgumentException e) {
                throw new IllegalArgumentException("Invalid percent-encoding in segment: " + seg, e);
            }
        }
        result.add(new PathSegmentImpl(seg));
    }
    return result;
}

