public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){
    if (box == null) {
        throw new IllegalArgumentException("box cannot be null");
    }
    try {
        double minX = box.getMinX();
        double maxX = box.getMaxX();
        double minY = box.getMinY();
        double maxY = box.getMaxY();

        if (maxX < minX) {
            throw new IllegalArgumentException("Box has invalid X bounds: minX > maxX");
        }

        double midX = (minX + maxX) / 2.0;

        Box2D left = new Box2D(minX, minY, midX, maxY);
        Box2D right = new Box2D(midX, minY, maxX, maxY);

        return new Pair<>(left, right);
    } catch (Exception e) {
        throw new IllegalArgumentException("Failed to split box along X axis", e);
    }
}

private void enlarge(final int size) {
    if (size < 0) {
        throw new IllegalArgumentException("size must be non‑negative");
    }
    // If there is already enough free space, nothing to do
    if (this.capacity - this.size >= size) {
        return;
    }
    // Compute a new capacity that is at least large enough for the requested
    // additional bytes, but grow the array to reduce the number of future
    // resizes.  Use the larger of double the current capacity or the exact
    // required capacity.
    int newCapacity = Math.max(this.capacity * 2, this.size + size);
    // Handle integer overflow
    if (newCapacity < 0) {
        newCapacity = Integer.MAX_VALUE;
    }
    // Allocate a new array and copy the existing data
    byte[] newArray = new byte[newCapacity];
    System.arraycopy(this.bytes, 0, newArray, 0, this.size);
    this.bytes = newArray;
    this.capacity = newCapacity;
}

