public String format(final LoggingEvent event){
    if (event == null) {
        return "";
    }
    try {
        StringBuilder sb = new StringBuilder();
        // Timestamp
        long ts = event.getTimeStamp();
        java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS");
        sb.append(sdf.format(new java.util.Date(ts)));
        sb.append(" [");
        // Level
        if (event.getLevel() != null) {
            sb.append(event.getLevel().toString());
        } else {
            sb.append("UNKNOWN");
        }
        sb.append("] ");
        // Thread name
        String thread = event.getThreadName();
        sb.append(thread != null ? thread : "unknown-thread");
        sb.append(" - ");
        // Logger name
        String logger = event.getLoggerName();
        sb.append(logger != null ? logger : "unknown-logger");
        sb.append(" - ");
        // Message
        Object msgObj = event.getMessage();
        sb.append(msgObj != null ? msgObj.toString() : "");
        // Throwable information
        if (event.getThrowableInformation() != null) {
            java.lang.Throwable t = event.getThrowableInformation().getThrowable();
            if (t != null) {
                sb.append(System.lineSeparator());
                java.io.StringWriter sw = new java.io.StringWriter();
                java.io.PrintWriter pw = new java.io.PrintWriter(sw);
                t.printStackTrace(pw);
                pw.flush();
                sb.append(sw.toString());
            }
        }
        return sb.toString();
    } catch (Exception e) {
        return "Error formatting LoggingEvent: " + e.getMessage();
    }
}

