public static int nextPrime(int desiredCapacity) {
    // Handle non-positive or very small capacities
    if (desiredCapacity <= 2) {
        return 2;
    }

    // Ensure we start with an odd number (except 2)
    int candidate = desiredCapacity;
    if (candidate % 2 == 0) {
        candidate++;
    }

    // Compute the upper bound for the 11% rule if applicable
    long limit = Integer.MAX_VALUE;
    if (desiredCapacity >= 1000) {
        // Use long to avoid overflow when multiplying
        limit = (long) Math.ceil(desiredCapacity * 1.11);
        if (limit > Integer.MAX_VALUE) {
            limit = Integer.MAX_VALUE;
        }
    }

    // Helper to test primality
    java.util.function.IntPredicate isPrime = n -> {
        if (n <= 1) return false;
        if (n <= 3) return true;
        if (n % 2 == 0) return false;
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) return false;
        }
        return true;
    };

    // Search for the next prime within the limit
    while (candidate <= limit) {
        if (isPrime.test(candidate)) {
            return candidate;
        }
        // Avoid overflow when incrementing
        if (candidate > Integer.MAX_VALUE - 2) {
            break;
        }
        candidate += 2;
    }

    // If no prime found within the limit, continue searching beyond it
    // (this may violate the 11% rule but ensures a prime is returned)
    while (candidate > 0) { // candidate will never be negative here
        if (isPrime.test(candidate)) {
            return candidate;
        }
        if (candidate > Integer.MAX_VALUE - 2) {
            break;
        }
        candidate += 2;
    }

    // Fallback: return the maximum integer value (unlikely to be prime)
    return Integer.MAX_VALUE;
}

