public String readString() throws IOException {
    // Read the length prefix (assumed to be a 4-byte signed integer)
    int length;
    try {
        length = in.readInt();
    } catch (EOFException e) {
        throw new IOException("Unexpected end of stream while reading string length", e);
    }

    // Validate length
    if (length < 0) {
        throw new IOException("Negative string length: " + length);
    }
    if (length == 0) {
        return "";
    }

    // Read the string bytes
    byte[] bytes = new byte[length];
    try {
        in.readFully(bytes);
    } catch (EOFException e) {
        throw new IOException("Unexpected end of stream while reading string data", e);
    } catch (OutOfMemoryError e) {
        throw new IOException("String length too large: " + length, e);
    }

    // Convert bytes to a UTF-8 string
    return new String(bytes, java.nio.charset.StandardCharsets.UTF_8);
}

private static int digitValue(final char c){
    // Handle ASCII digits 0-9
    if (c >= '0' && c <= '9') {
        return c - '0';
    }
    // Handle ASCII uppercase letters A-Z
    if (c >= 'A' && c <= 'Z') {
        return c - 'A' + 10;
    }
    // Handle ASCII lowercase letters a-z
    if (c >= 'a' && c <= 'z') {
        return c - 'a' + 10;
    }
    // Non-ASCII or non-digit characters are not accepted
