private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("Predicate must not be null");
    }
    if (start == null || stop == null) {
        throw new IllegalArgumentException("Start and stop nodes must not be null");
    }

    // Create a circulator starting at the start node
    OuterFaceCirculator circ = new OuterFaceCirculator(start);

    // If the start node already satisfies the predicate, return it immediately
    if (predicate.test(circ.getNode())) {
        return circ;
    }

    // If start and stop are the same, return the circulator at stop
    if (start.equals(stop)) {
        return circ;
    }

    // Traverse the outer face until we reach the stop node or find a node that satisfies the predicate
    while (!circ.getNode().equals(stop)) {
        // Move to the next node in the specified direction
        circ = (dir >= 0) ? circ.next() : circ.prev();

        // Safety check: if the circulator becomes null, break to avoid an infinite loop
        if (circ == null) {
            break;
        }

        // Check the predicate on the current node
        if (predicate.test(circ.getNode())) {
            return circ;
        }
    }

    // If we exit the loop, we are at the stop node (or the circulator is null). Return the circulator at stop.
    return circ;
}

