            case WEBSOCKET:
            case LONG_POLLING:
                if (!r.isSuspended()) {
                    r.suspend();
                }
                break;
            default:
                // No suspension needed for other transports
                break;
        }
    } catch (Exception e) {
        // Swallow any exception to avoid disrupting the inspection chain
    }
    return Action.CONTINUE;
}

