private String unescapeId(String input) {
    if (input == null) {
        return null;
    }
    int len = input.length();
    if (len == 0) {
        return "";
    }
    // If quoted, strip outer quotes
    boolean quoted = false;
    if (len >= 2 && input.charAt(0) == '"' && input.charAt(len-1) == '"') {
        quoted = true;
        input = input.substring(1, len-1);
        len = input.length();
    }
    StringBuilder sb = new StringBuilder(len);
    for (int i = 0; i < len; i++) {
        char c = input.charAt(i);
        if (c == '\\') {
            if (i + 1 >= len) {
                // trailing backslash, treat as literal backslash
                sb.append('\\');
                break;
            }
            char next = input.charAt(++i);
            switch (next) {
                case 'n': sb.append('\n'); break;
                case 't': sb.append('\t'); break;
                case 'r': sb.append('\r'); break;
                case 'b': sb.append('\b'); break;
                case 'f': sb.append('\f'); break;
                case 'v': sb.append('\u000B'); break; // vertical tab
                case '0': sb.append('\0'); break;
                case '\\': sb.append('\\'); break;
                case '"': sb.append('"'); break;
                case 'x':
                    // parse two hex digits
                    if (i + 2 <= len - 1) {
                        String hex = input.substring(i+1, i+3);
                        try {
                            int val = Integer.parseInt(hex, 16);
                            sb.append((char) val);
                            i += 2;
                        } catch (NumberFormatException e) {
                            // invalid hex, treat as literal
                            sb.append('x');
                        }
                    } else {
                        // not enough digits, treat as literal
                        sb.append('x');
                    }
                    break;
                case 'u':
                    // parse four hex digits
                    if (i + 4 <= len - 1) {
                        String hex = input.substring(i+1, i+5);
                        try {
                            int val = Integer.parseInt(hex, 16);
                            sb.append((char) val);
                            i += 4;
                        } catch (NumberFormatException e) {
                            sb.append('u');
                        }
                    } else {
                        sb.append('u');
                    }
                    break;
                case 'U':
                    // parse eight hex digits
                    if (i + 8 <= len - 1) {
                        String hex = input.substring(i+1, i+9);
                        try {
