public List<SequenceRange> buildSequenceRanges(){
    java.util.List<SequenceRange> ranges = new java.util.ArrayList<>();
    try {
        // Attempt to build ranges from current profiles
        if (this.currentProfiles == null) {
            return ranges;
        }
        for (Profile profile : this.currentProfiles) {
            if (profile == null) continue;
            java.util.List<Segment> segments = profile.getSegments();
            if (segments == null) continue;
            for (Segment segment : segments) {
                if (segment == null) continue;
                java.util.List<Snapshot> snapshots = segment.getSnapshots();
                if (snapshots == null) continue;
                for (Snapshot snapshot : snapshots) {
                    if (snapshot == null) continue;
                    java.util.List<SearchSequence> sequences = snapshot.getSearchSequences();
                    if (sequences == null) continue;
                    for (SearchSequence seq : sequences) {
                        if (seq == null) continue;
                        int start = seq.getStart();
                        int end = seq.getEnd();
                        ranges.add(new SequenceRange(start, end));
                    }
                }
            }
        }
    } catch (Exception e) {
        // ignore and return what we have
    }
    return ranges;
}

