}

public static boolean arrayequals(byte[] a, byte[] b, int count) {
    // If count is zero or negative, nothing to compare; treat as equal
    if (count <= 0) {
        return true;
    }
    // If either array is null, they cannot match the requested count
    if (a == null || b == null) {
        return false;
    }
    // If count exceeds either array's length, they cannot match
    if (count > a.length || count > b.length) {
        return false;
    }
    // Compare byte by byte
    for (int i = 0; i < count; i++) {
        if (a[i] != b[i]) {
            return false;
        }
    }
    return true;
}

