int parseType(String desc, int idx) {
    char c = desc.charAt(idx);
    switch(c) {
        case 'B': case 'C': case 'D': case 'F': case 'I': case 'S': case 'Z':
            return new int[]{1, idx+1};
        case 'J': case 'D': // double and long
            return new int[]{2, idx+1};
        case 'L':
            int semicolon = desc.indexOf(';', idx+1);
            if (semicolon == -1) throw new IllegalArgumentException("Invalid object type descriptor: missing ';'");
            return new int[]{1, semicolon+1};
        case '[':
            // array type: skip all '[' then parse component
            int arrayIdx = idx;
            while (arrayIdx < desc.length() && desc.charAt(arrayIdx) == '[') {
                arrayIdx++;
            }
            if (arrayIdx >= desc.length()) {
                throw new IllegalArgumentException("Invalid array type descriptor: missing component type");
            }
            // parse component type
            int[] comp = parseType(desc, arrayIdx);
            // array type occupies one slot
            return new int[]{1, comp[1]};
        default:
            throw new IllegalArgumentException("Invalid type descriptor at index " + idx + ": " + c);
    }
}

