private List<Integer> computeUpperBounds(List<K> keys) {
    List<Integer> bounds = new ArrayList<>();
    if (keys == null || keys.isEmpty()) {
        return bounds;
    }
    for (K key : keys) {
        int bound = keys.size(); // default: no greater element
        if (key == null) {
            // Treat null as less than any non‑null key; upper bound is 0
            bound = 0;
        } else {
            for (int i = 0; i < keys.size(); i++) {
                K candidate = keys.get(i);
                if (candidate == null) {
                    continue;
                }
                try {
                    @SuppressWarnings("unchecked")
                    Comparable<K> compKey = (Comparable<K>) key;
                    if (compKey.compareTo(candidate) < 0) {
                        bound = i;
                        break;
                    }
                } catch (ClassCastException e) {
                    // If key is not comparable, skip comparison
                    break;
                }
            }
        }
        bounds.add(bound);
    }
    return bounds;
}

