static String[] toNoNullStringArray(Object[] array){
    // Return null if the input array itself is null
    if (array == null) {
        return null;
    }

    // Count non‑null elements
    int nonNullCount = 0;
    for (Object obj : array) {
        if (obj != null) {
            nonNullCount++;
        }
    }

    // If there are no nulls and the array is already a String[], just return it
    if (nonNullCount == array.length && array instanceof String[]) {
        return (String[]) array;
    }

    // Create a new array to hold the non‑null elements
    String[] result = new String[nonNullCount];
    int idx = 0;
    for (Object obj : array) {
        if (obj != null) {
            if (!(obj instanceof String)) {
                throw new IllegalArgumentException(
                    "Array contains non-String element: " + obj.getClass().getName());
            }
            result[idx++] = (String) obj;
        }
    }
    return result;
}

public static int indexOfExtension(String filename) {
    if (filename == null) {
        return -1;
    }
    int dotIndex = filename.lastIndexOf('.');
    if (dotIndex == -1) {
        return -1;
    }
    int slashIndex = filename.lastIndexOf('/');
    int backslashIndex = filename.lastIndexOf('\\');
    int lastSeparatorIndex = Math.max(slashIndex, backslashIndex);
    return dotIndex > lastSeparatorIndex ? dotIndex : -1;
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    try {
        // If threshold is non-positive, consider it expired immediately
        if (expiredThreshold <= 0) {
            return true;
        }
        long currentTime = System.currentTimeMillis();
        // If the timestamp is in the future, it cannot be expired yet
        if (timestamp > currentTime) {
            return false;
        }
        // Expired if the elapsed time since timestamp exceeds the threshold
        return currentTime - timestamp > expiredThreshold;
    } catch (Exception e) {
        // In case of any unexpected error, treat as expired to be safe
        return true;
    }
}

public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    // Validate inputs
    if (str == null || substring == null) {
        return false;
    }
    int strLen = str.length();
    int subLen = substring.length();

    // Index must be within bounds and allow the substring to fit
    if (index < 0 || index > strLen - subLen) {
        return false;
    }

    // Compare characters one by one
    for (int i = 0; i < subLen; i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

